import{_ as a,b as e,c as o,I as s}from"./chunks/framework.C6cPs9Ia.js";const d=JSON.parse('{"title":"小学时代的网页游戏","description":"关于洛克王国、赛尔号和 4399 小游戏的童年记忆——网页游戏的黄金年代","frontmatter":{"title":"小学时代的网页游戏","date":"2026-09-16T00:00:00.000Z","tags":["网页游戏","怀旧",4399],"cover":"/LQY/images/hero.jpg","head":[["meta",{"name":"description","content":"关于洛克王国、赛尔号和 4399 小游戏的童年记忆——网页游戏的黄金年代"}],["meta",{"name":"keywords","content":"4399, 网页游戏, 洛克王国, 赛尔号, 摩尔庄园, 怀旧, Flash"}]]},"headers":[],"relativePath":"posts/webgame-museum.md","filePath":"posts/webgame-museum.md"}'),r={name:"posts/webgame-museum.md"};function n(l,t,i,u,p,h){return e(),o("div",null,[...t[0]||(t[0]=[s('<p>周末整理旧硬盘，翻出几张小学时的游戏截图，一整个下午都在回忆里出不来。写下来，存个档。</p><hr><h2 id="宠物养成三巨头" tabindex="-1">宠物养成三巨头 <a class="header-anchor" href="#宠物养成三巨头" aria-label="Permalink to &quot;宠物养成三巨头&quot;">​</a></h2><p><strong>洛克王国</strong>——我的第一个&quot;电子宠物&quot;。格里芬院长的剧情、宠物的进化链、每周五更新的新宠图鉴，那时候一周最期待的不是周末，是周五下午放学冲回家打开电脑。</p><p><strong>赛尔号</strong>——雷伊登场那阵子，全班课间讨论的主题都变成了&quot;你拿到雷伊没有&quot;。盖亚和雷伊的对决海报，我在书桌前的墙上贴了整整三年。</p><p><strong>摩尔庄园</strong>——严格来说我不是种菜玩家，我是去看拉姆的。小家伙饿的时候，我拿零花钱买道具的手速，比现在抢任何东西都快。</p><p>这三个游戏有个共同点：<strong>很多事要等</strong>。等作物成熟、等蛋孵化、等周五更新。现在动不动&quot;一键领取&quot;，反而没了那个味道。</p><h2 id="_4399-小游戏" tabindex="-1">4399 小游戏 <a class="header-anchor" href="#_4399-小游戏" aria-label="Permalink to &quot;4399 小游戏&quot;">​</a></h2><ul><li><strong>死神 VS 火影</strong>：双人模式，一人半边键盘，和表哥打到键盘差点分家。连招表手抄在数学本最后一页</li><li><strong>黄金矿工</strong>：人生第一次理解&quot;该出手时就出手&quot;，以及抓错石头有多亏</li><li><strong>森林冰火人</strong>：和同桌合作，三分钟友尽，五分钟和好，如此循环</li><li><strong>造梦西游</strong>：我玩的第一款有&quot;刷装备&quot;概念的游戏，悟空的棒子敲下去的那一声，现在还记得</li></ul><h2 id="关于-flash" tabindex="-1">关于 Flash <a class="header-anchor" href="#关于-flash" aria-label="Permalink to &quot;关于 Flash&quot;">​</a></h2><p>Flash 停服那天，我在某个怀旧站上又玩了一局黄金矿工。画面还是糊糊的，BGM 还是那一段，钩子甩下去还是那个抛物线。</p><p>物理引擎没变，变的是屏幕前的人——当年写完作业能玩一下午的小孩，现在要拿月考排名来兑换游戏时间。</p><p>有人说网页游戏的时代结束了。我觉得倒也没有，它们只是搬了家：搬进一些还能打开的怀旧站里，也搬进每个还记得&quot;4399 是四个彩色数字&quot;的人的记忆里。</p><h2 id="小计划" tabindex="-1">小计划 <a class="header-anchor" href="#小计划" aria-label="Permalink to &quot;小计划&quot;">​</a></h2><p>最近想做一个&quot;网页游戏编年史&quot;的整理，按年份把记忆里的游戏梳理一遍。工程量不小，可能会拆成好几篇文章慢慢写。</p><p>如果你也有想回顾的老游戏，评论区说一下，我排进计划里。</p>',16)])])}const c=a(r,[["render",n]]);export{d as __pageData,c as default};
